#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

# A wizard calls only some of the library's helpers; the rest stay so every copy matches.
# shellcheck disable=SC2329
set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
	BOLD=$(tput bold)
	DIM=$(tput dim)
	RESET=$(tput sgr0)
	BLUE=$(tput setaf 4)
	GREEN=$(tput setaf 2)
	YELLOW=$(tput setaf 3)
else
	BOLD=""
	DIM=""
	RESET=""
	BLUE=""
	GREEN=""
	YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
	[[ -t 1 ]] || return 0
	if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
	printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
	_clear
	printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
	printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
	printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
	printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
	printf '  later, since it remembers values already saved.%s\n' "$RESET"
	pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
	_clear
	_STAGE_INDEX=$((_STAGE_INDEX + 1))
	printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
		"$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say() { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
	local url="$1"
	printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
	{
		if command -v wslview >/dev/null 2>&1; then
			wslview "$url"
		elif command -v explorer.exe >/dev/null 2>&1; then
			explorer.exe "$url"
		elif command -v xdg-open >/dev/null 2>&1; then
			xdg-open "$url"
		elif command -v open >/dev/null 2>&1; then
			open "$url"
		else false; fi
	} >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
	printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
	read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
	local reply=""
	printf '  %s? %s [y/N] ' "$YELLOW" "$1"
	read -r reply || true
	[[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
	[[ -f "$ENV_FILE" ]] || return 1
	local line value sq="'\\''"
	line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
	value="${line#*=}"
	if [[ "$value" == \'*\' ]]; then
		value="${value:1:${#value}-2}"
		value="${value//"$sq"/\'}"
	elif [[ "$value" == \"*\" ]]; then
		value="${value:1:${#value}-2}"
		[[ "$value" == *[\\\$\"]* ]] && return 1 # escapes, $ or ": can't decode safely; ask again
	fi
	printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
	local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
	current=$(_existing "$key" || true)
	# Readline needs the colour codes wrapped in \001..\002 to place the cursor.
	p="  $s$BOLD$e$prompt$s$RESET$e "
	[[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps current]$s$RESET$e "
	read -e -r -p "$p" input || rc=1
	if ((rc)) && [[ -z "$input" ]]; then return 1; fi
	[[ -z "$input" && -n "$current" ]] && input="$current"
	printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
	local key="$1" prompt="$2" current input rc=0
	current=$(_existing "$key" || true)
	if [[ -n "$current" ]]; then
		printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
	else
		printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
	fi
	read -rs input || rc=1
	printf '\n'
	if ((rc)) && [[ -z "$input" ]]; then return 1; fi
	[[ -z "$input" && -n "$current" ]] && input="$current"
	printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
	local key="$1" value="$2" tmp sq="'\\''"
	[[ -e "$ENV_FILE" ]] || (umask 077 && : >"$ENV_FILE")
	tmp=$(mktemp)
	grep -vE "^${key}=" "$ENV_FILE" >"$tmp" || true
	printf "%s='%s'\n" "$key" "${value//\'/$sq}" >>"$tmp"
	cat "$tmp" >"$ENV_FILE"
	rm -f "$tmp"
	printf -v "$key" '%s' "$value"
	WRITTEN_ENV+=("$key")
	printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
	local name="$1" value="$2"
	if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
		if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
			WRITTEN_SECRET+=("$name")
			printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
			return
		fi
	fi
	SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
	warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
	local name="$1" value="$2"
	if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
		if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
			printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
			return
		fi
	fi
	SKIPPED+=("GitHub variable $name")
	warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
	_clear
	printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
	((${#WRITTEN_ENV[@]})) && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
	((${#WRITTEN_SECRET[@]})) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
	if ((${#SKIPPED[@]})); then
		printf '\n'
		warn "still to do by hand:"
		for s in "${SKIPPED[@]}"; do note "  - $s"; done
	fi
	printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

	TOTAL_STAGES=17

	cd "$(git rev-parse --show-toplevel)"
	REPO="Fullchee/journal-native"
	SITE="https://journal.fullchee.workers.dev"
	CF_ACCOUNT="296a4e1f99974dd2c529d71ef1be56c3"
	# The old app's checkout: it owns the Pages deploy, the D1 database and the Google client.
	JOURNAL="$(cd .. && pwd)/journal"
	DB="fullchee-dashboard"
	GH_TOKEN=$(gh auth token --user Fullchee)
	export GH_TOKEN
	# Results outlive the run, so the gate can span days (reboots, reminders) and resume.
	mkdir -p "$HOME/.cache"
	ENV_FILE="$HOME/.cache/journal-native-gate.env"

	ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

	# record KEY "check": asks pass/fail/skip plus a note, saved as "pass: note". A saved pass is kept unless redone.
	record() {
		local key="$1" check="$2" current verdict="" note=""
		current=$(_existing "$key" || true)
		if [[ "$current" == pass* ]] && ! confirm "Already passed ($current). Redo \"$check\"?"; then return 0; fi
		while [[ ! "$verdict" =~ ^(pass|fail|skip)$ ]]; do
			printf '  %s? %s%s [pass/fail/skip] ' "$YELLOW" "$check" "$RESET"
			read -r verdict || verdict="skip"
			case "$verdict" in p*) verdict=pass ;; f*) verdict=fail ;; s*) verdict=skip ;; esac
		done
		read -e -r -p "  Note (Enter for none): " note || true
		write_env "$key" "$verdict${note:+: $note}"
	}

	# result KEY prints a saved verdict, or "not checked".
	result() { _existing "$1" || printf 'not checked'; }

	# journal_secret KEY reads a value the journal checkout keeps in its git-ignored .dev.vars.
	journal_secret() {
		local ENV_FILE="$JOURNAL/.dev.vars"
		_existing "$1"
	}

	# Access answers an unsigned request with a redirect to its login page, never a 200.
	# Google's consent screen links to these, so they must load without a login.
	public_pages_open() {
		local path
		for path in privacy terms; do
			[[ "$(curl -s -o /dev/null -w '%{http_code}' "$SITE/$path")" == 200 ]] || return 1
		done
	}

	site_is_guarded() {
		local code
		code=$(curl -s -o /dev/null -w '%{http_code}' "$SITE/")
		[[ "$code" != 200 ]]
	}

	# 0033 and 0034 were applied by hand before their deploys, so no push has proven Pages applies one yet.
	DEPLOY_CHECK="0035_deploy_check.sql"
	# Pushes from a throwaway worktree of origin/main, so the journal checkout's own work is untouched.
	push_deploy_check() {
		local tree pushed=0
		tree=$(mktemp -d)/journal-deploy-check
		git -C "$JOURNAL" fetch -q origin main
		git -C "$JOURNAL" worktree add -q --detach "$tree" origin/main
		# The worktree has no node_modules, so journal's hooks can't run; Pages builds the commit anyway.
		printf -- '-- No-op: proves a push to main applies migrations on the Pages deploy (#62).\nSELECT 1;\n' >"$tree/migrations/$DEPLOY_CHECK" &&
			git -C "$tree" add "migrations/$DEPLOY_CHECK" &&
			git -C "$tree" commit -q --no-verify -m "chore: add a no-op migration to prove deploys apply migrations (#62)" &&
			git -C "$tree" push -q --no-verify origin HEAD:main &&
			pushed=1
		git -C "$JOURNAL" worktree remove --force "$tree"
		((pushed))
	}

	# Access takes up to a minute to start guarding a host after it's saved.
	becomes_guarded() {
		local _
		for _ in 1 2 3 4 5 6; do
			site_is_guarded && return 0
			sleep 10
		done
		return 1
	}

	migration_applied() {
		bunx wrangler@4 d1 execute "$DB" --remote --json \
			--command "select name from d1_migrations where name = '$DEPLOY_CHECK'" 2>/dev/null | grep -q "$DEPLOY_CHECK"
	}

	banner "journal-native: everything waiting on the owner"
	say "Setup first (#38, #59, #62, #66), then the phone gate (#32)."
	note "Passed steps are remembered in $ENV_FILE, so re-runs skip ahead."
	pause

	stage "Guard the web site with Access"
	say "Until Access guards the site, the API answers 401: no login token reaches it."
	if site_is_guarded; then
		ok "$SITE already asks for a login"
		write_env GATE_ACCESS "pass: the site asks for a login"
	else
		open_url "https://dash.cloudflare.com/$CF_ACCOUNT/one/access-controls/apps"
		step "Access → Applications → fullchee-dashboard → Configure."
		step "Under public hostnames, add: journal.fullchee.workers.dev"
		step "Save. Keep the same policies: one app means one audience, so the API trusts its tokens."
		note "Don't create a new Access app: the API would reject its tokens."
		pause "Press Enter once saved (or if Cloudflare rejected the hostname)"
		if becomes_guarded; then
			ok "$SITE now asks for a login"
			write_env GATE_ACCESS "pass: hostname added to the fullchee-dashboard Access app"
		else
			warn "The site still loads without a login."
			if confirm "Did Cloudflare reject the workers.dev hostname?"; then
				open_url "https://dash.cloudflare.com/$CF_ACCOUNT/workers/services/view/journal/production/settings"
				step "Settings → Domains & Routes → Production (journal.fullchee.workers.dev) → Enable Access."
				step "Copy the AUD tag Cloudflare shows (or: Access → Applications → the new app → Overview)."
				step "Preview (*-journal.fullchee.workers.dev): turn it off; CI never uses preview URLs."
				step "Copy the owner policy from fullchee-dashboard onto the new app."
				pause "Press Enter once enabled"
				if becomes_guarded; then
					ok "$SITE now asks for a login"
				else warn "Still public; Access can take a minute. Re-run later."; fi
				write_env GATE_ACCESS "fallback: separate Access app on workers.dev; the API must accept its audience too"
				ask ACCESS_AUD "Paste the new app's AUD tag:"
				write_env ACCESS_AUD "$ACCESS_AUD"
				SKIPPED+=("Tell Claude: make the API accept the second Access audience in $ENV_FILE (ACCESS_AUD)")
			else
				SKIPPED+=("Access: the site is still public; re-run this wizard in a few minutes")
			fi
		fi
	fi
	pause

	stage "Keep the privacy and terms pages public"
	say "Google's consent screen links to /privacy and /terms, so Access must let anyone read them."
	if ! site_is_guarded; then
		warn "Access doesn't guard $SITE yet, so this can't be checked. Re-run after stage 1."
		SKIPPED+=("Public pages: re-run this wizard once Access guards the site")
	elif public_pages_open; then
		ok "/privacy and /terms load without a login"
		write_env GATE_PUBLIC_PAGES "pass: both pages load without a login"
	else
		open_url "https://dash.cloudflare.com/$CF_ACCOUNT/one/access-controls/apps"
		step "Access → Applications → Journal public pages → Configure."
		step "Add a public hostname: journal.fullchee.workers.dev, path: privacy"
		step "Add another: journal.fullchee.workers.dev, path: terms"
		step "Save. Keep its Bypass policy (Include → Everyone)."
		note "No 'Journal public pages' app? Add a Self-hosted app with those two hostnames and a Bypass policy for Everyone."
		pause "Press Enter once saved"
		if public_pages_open; then
			ok "/privacy and /terms load without a login"
			write_env GATE_PUBLIC_PAGES "pass: both pages load without a login"
		else
			warn "They still ask for a login; Access can take a minute. Re-run later."
			write_env GATE_PUBLIC_PAGES "fail: the pages still ask for a login"
		fi
	fi
	pause

	stage "Sign in on the web site"
	open_url "$SITE"
	step "Sign in with your usual Access login."
	step "Check that Today loads your data, not an error or an empty screen."
	record GATE_WEB "Web: sign-in works and Today shows data"
	pause

	stage "A new migration applies on deploy (#62, #66)"
	say "Pushes a no-op migration ($DEPLOY_CHECK, 'SELECT 1') to journal's main."
	say "Then it waits for the Pages deploy to record it in d1_migrations."
	if migration_applied; then
		ok "$DEPLOY_CHECK is already applied"
		write_env GATE_MIGRATIONS "pass: Pages applied $DEPLOY_CHECK on deploy"
	elif confirm "Push it to Fullchee/journal main now? (It runs on the production database.)"; then
		if push_deploy_check; then
			ok "pushed to journal main"
		else
			warn "The push failed; nothing reached journal's main."
			exit 1
		fi
		say "Waiting up to 15 minutes for the Pages deploy…"
		applied=0
		for _ in $(seq 30); do
			if migration_applied; then
				applied=1
				break
			fi
			sleep 30
		done
		if ((applied)); then
			ok "Pages applied $DEPLOY_CHECK on its own"
			write_env GATE_MIGRATIONS "pass: Pages applied $DEPLOY_CHECK on deploy"
		else
			warn "Not applied after 15 minutes. Check the deploy log in the Pages dashboard."
			write_env GATE_MIGRATIONS "fail: $DEPLOY_CHECK not applied 15 minutes after the push"
		fi
	else
		SKIPPED+=("Migration check (#62): re-run this wizard to push $DEPLOY_CHECK")
	fi
	pause

	stage "Calendar access that doesn't expire (#59)"
	say "journal's own wizard publishes the Google OAuth app and gets a lasting refresh token."
	note "It saves the token in $JOURNAL/.dev.vars; the next stages copy it to the journal Worker."
	if [[ -n "$(journal_secret GOOGLE_REFRESH_TOKEN || true)" ]] && ! confirm "A refresh token is already saved. Run the calendar wizard again?"; then
		ok "keeping the saved refresh token"
	elif confirm "Run journal's calendar wizard now?"; then
		(cd "$JOURNAL" && ./scripts/google-calendar-setup.sh) || warn "The calendar wizard stopped early."
	fi
	if [[ -n "$(journal_secret GOOGLE_REFRESH_TOKEN || true)" ]]; then
		write_env GATE_CALENDAR "pass: refresh token saved after publishing"
	else
		SKIPPED+=("Calendar (#59): run $JOURNAL/scripts/google-calendar-setup.sh")
	fi
	pause

	stage "Point Google's consent screen at the new site (#59)"
	say "Branding still links fullchee-dashboard.pages.dev, which retires after the cutover (#38)."
	if [[ "$(result GATE_PUBLIC_PAGES)" != pass* ]]; then
		warn "Make /privacy and /terms public first (stage 2), or Google can't read them."
		SKIPPED+=("Google Branding: re-run once the privacy and terms pages are public")
	else
		open_url "https://console.cloud.google.com/auth/branding"
		step "Pick the project that owns the Journal app client."
		step "Application home page: $SITE"
		step "Privacy policy: $SITE/privacy   Terms of service: $SITE/terms"
		step "Authorized domains → Add domain: fullchee.workers.dev. Keep fullchee-dashboard.pages.dev until the cutover."
		step "Save."
		note "Publishing status must stay 'In production'; changing Branding doesn't reset it."
		record GATE_BRANDING "Branding saved with the journal.fullchee.workers.dev links"
	fi
	pause

	stage "Let CI's deploy token reach D1 and R2 (#38)"
	say "Moving the API into the journal Worker needs these bindings at deploy time."
	open_url "https://dash.cloudflare.com/profile/api-tokens"
	step "Find the token stored as CLOUDFLARE_API_TOKEN (Account · Workers Scripts · Edit) → Edit."
	step "Add: Account · D1 · Edit."
	step "Add: Account · Workers R2 Storage · Edit."
	step "Continue to summary → Update token. The token's value doesn't change."
	record GATE_TOKEN "CI token has D1 Edit and Workers R2 Storage Edit"
	pause

	stage "Put the API secrets on the journal Worker (#38)"
	say "Copies TODOIST_TOKEN and the three GOOGLE_* values from $JOURNAL/.dev.vars."
	note "The Worker only proxies today; the ported API reads these once it goes live."
	missing=()
	for name in TODOIST_TOKEN GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET GOOGLE_REFRESH_TOKEN; do
		[[ -n "$(journal_secret "$name" || true)" ]] || missing+=("$name")
	done
	if ((${#missing[@]})); then
		warn "Missing from $JOURNAL/.dev.vars: ${missing[*]}"
		SKIPPED+=("Worker secrets: add ${missing[*]} to $JOURNAL/.dev.vars, then re-run")
	elif confirm "Upload all four as secrets on the journal Worker?"; then
		failed=0
		for name in TODOIST_TOKEN GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET GOOGLE_REFRESH_TOKEN; do
			if journal_secret "$name" | bunx wrangler@4 secret put "$name" --name journal >/dev/null 2>&1; then
				ok "Worker secret $name"
			else
				failed=1
				warn "couldn't set $name"
			fi
		done
		if ((failed)); then
			write_env GATE_SECRETS "fail: wrangler secret put failed"
		else write_env GATE_SECRETS "pass: four secrets on the journal Worker"; fi
	fi
	pause

	stage "Install the latest APK"
	say "The gate checks the APK on your phone, so it needs the current native code."
	note "JS-only changes arrive by EAS Update; only a native change needs a new APK."
	if confirm "Build a fresh APK now? (13 to 35 minutes)"; then
		bun run android:apk
		step "Install journal.apk on the phone (the script opened Finder and Drive)."
	fi
	step "In the Capacitor app, turn its alarms off, so nothing rings twice."
	step "Open the new app and sign in."
	pause "Press Enter once the new app is installed and signed in"

	stage "Alarms ring with the phone asleep"
	step "Make two test Habits due in about 5 minutes: one alarm kind, one persistent kind."
	step "Lock the phone and leave it."
	note "Expected: the alarm rings over the lock screen until Dismiss; the persistent one shows and stays."
	pause "Press Enter once both times have passed"
	record GATE_ALARM_ASLEEP "Both alarm kinds fired on time while asleep"
	pause

	stage "Alarms survive a reboot"
	step "Move both test Habits to about 5 minutes from now."
	step "Reboot the phone. Don't open the app afterwards."
	pause "Press Enter once both times have passed"
	record GATE_ALARM_REBOOT "Both alarm kinds fired on time after a reboot"
	step "Delete the two test Habits."
	pause

	stage "Connection reminders arrive"
	step "Give a Connection a meetup reminder and a date reminder a few minutes ahead."
	step "Wait for both."
	record GATE_CONNECTIONS "Connection meetup and date reminders arrived"
	pause

	stage "Widgets open the right screen"
	step "Add the three widgets to the home screen: Log, Check-in and Alarms."
	step "Tap each one."
	note "Expected: Log opens the log box, Check-in opens a Check-in, Alarms opens Habits."
	record GATE_WIDGETS "All three widgets opened the right screen in the new app"
	pause

	stage "Core screens work"
	step "Today: it loads and shows due Habits and Connections."
	step "Save a Check-in and check a Habit (try one in airplane mode; it sends when back online)."
	step "Log box: send a message and get a reply."
	record GATE_CORE "Today, Check-in, Habit checks and the log box work"
	pause

	stage "Habit images work offline"
	step "Online: add a photo to a Habit's description and save."
	step "Check the photo shows."
	step "Turn on airplane mode, close and reopen the app, and open that Habit again."
	record GATE_IMAGES "The photo shows after save, and again in airplane mode"
	pause

	stage "Over-the-air updates reach the phone"
	say "Needs a JS-only change on main after this APK was installed."
	step "Push a visible JS-only change, or ask Claude for one (e.g. a label tweak)."
	pause "Press Enter once it's pushed"
	say "Waiting for CI's update job on the latest main push…"
	run_id=$(gh run list -R "$REPO" -b main -L 1 --json databaseId --jq '.[0].databaseId')
	if gh run watch "$run_id" -R "$REPO" --exit-status >/dev/null; then
		ok "CI published the update"
	else warn "CI failed; check: gh run view $run_id -R $REPO"; fi
	step "Close the app fully and open it. Do it twice."
	step "Check that the change shows."
	record GATE_UPDATES "The JS change reached the APK after two restarts"
	pause

	stage "Record the results on #38 and #32"
	setup="Owner setup, $(date +%F), from \`scripts/owner-gate.sh\`:

| Step | Result |
|---|---|
| Access on the web site (#38) | $(result GATE_ACCESS) |
| Web sign-in (#38) | $(result GATE_WEB) |
| Migration applied on deploy (#62) | $(result GATE_MIGRATIONS) |
| Privacy and terms public | $(result GATE_PUBLIC_PAGES) |
| Calendar token after publishing (#59) | $(result GATE_CALENDAR) |
| Google Branding on the new site (#59) | $(result GATE_BRANDING) |
| CI token D1 + R2 (#38) | $(result GATE_TOKEN) |
| Worker secrets (#38) | $(result GATE_SECRETS) |"
	gate="Gate results, $(date +%F), from \`scripts/owner-gate.sh\`:

| Check | Result |
|---|---|
| Access on the web site | $(result GATE_ACCESS) |
| Web sign-in | $(result GATE_WEB) |
| Alarms, phone asleep | $(result GATE_ALARM_ASLEEP) |
| Alarms, after reboot | $(result GATE_ALARM_REBOOT) |
| Connection reminders | $(result GATE_CONNECTIONS) |
| Widgets | $(result GATE_WIDGETS) |
| Today, Check-in, Habit checks, log box | $(result GATE_CORE) |
| Habit images offline | $(result GATE_IMAGES) |
| OTA update | $(result GATE_UPDATES) |"
	printf '%s\n\n' "$setup"
	if confirm "Post the setup results as a comment on #38?"; then
		gh issue comment 38 -R "$REPO" --body "$setup" >/dev/null && ok "posted to #38"
	fi
	SKIPPED+=("Tell Claude \"owner setup done\": it switches the API over (#38) and closes #59, #62 and #66")
	_clear
	printf '%s\n\n' "$gate"
	if confirm "Post the gate results as a comment on #32?"; then
		gh issue comment 32 -R "$REPO" --body "$gate" >/dev/null && ok "posted to #32"
	else
		SKIPPED+=("post the gate results on #32 (re-run this wizard; passed checks are remembered)")
	fi
	failed=0
	for key in GATE_ALARM_ASLEEP GATE_ALARM_REBOOT GATE_CONNECTIONS GATE_WIDGETS GATE_CORE GATE_IMAGES GATE_UPDATES; do
		[[ "$(result "$key")" == pass* ]] || failed=1
	done
	if ((failed)); then
		warn "Not every phone check passed: keep the Capacitor app installed."
		SKIPPED+=("Tell Claude which checks failed; re-run this wizard after the fixes")
	elif confirm "Every phone check passed. Uninstall the Capacitor app now? (You can't undo this.)"; then
		step "Long-press the old Journal app → Uninstall."
		pause "Press Enter once uninstalled"
		ok "Capacitor app gone"
		SKIPPED+=("Tell Claude \"gate done\" to close #32 and unblock the web cutover (#38)")
	fi
	pause

	finish
	note "Saved results: $ENV_FILE (delete it to start over)."
	printf '\n'
}

run_wizard "$@"
exit
